import{_ as i,o as t,c as a,a2 as r}from"./chunks/framework.DgVVaeR-.js";const _=JSON.parse('{"title":"Pixiv 通報機能の実装メモ","description":"","frontmatter":{},"headers":[],"relativePath":"pixiv-report-implementation.md","filePath":"pixiv-report-implementation.md","lastUpdated":1790997551000}'),l={name:"pixiv-report-implementation.md"};function o(p,e,d,n,c,s){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="pixiv-通報機能の実装メモ" tabindex="-1">Pixiv 通報機能の実装メモ <a class="header-anchor" href="#pixiv-通報機能の実装メモ" aria-label="Permalink to &quot;Pixiv 通報機能の実装メモ&quot;">​</a></h1><h2 id="pixez-flutter-の解析結果" tabindex="-1">pixez-flutter の解析結果 <a class="header-anchor" href="#pixez-flutter-の解析結果" aria-label="Permalink to &quot;pixez-flutter の解析結果&quot;">​</a></h2><p>参照したローカルソースでは、<code>lib/page/report/report_items_page.dart</code> は理由一覧を表示しますが、選択した理由をコールバックに渡していません。</p><ul><li><code>lib/page/picture/illust_lighting_page.dart</code>: Android の送信操作は <code>muteStore.insertBanIllusts</code> を実行します。</li><li><code>lib/page/user/users_page.dart</code>: 送信操作は <code>muteStore.insertBanUserId</code> を実行します。</li><li><code>lib/page/comment/comment_page.dart</code>: 通報画面への導線がありますが、この画面自体に Pixiv API 送信処理はありません。</li></ul><p>この実装から Pixiv 運営への送信 API や理由コードは確認できません。ローカルの非表示処理を送信成功として流用しないようにしています。</p><h2 id="palleria-の変更" tabindex="-1">Palleria の変更 <a class="header-anchor" href="#palleria-の変更" aria-label="Permalink to &quot;Palleria の変更&quot;">​</a></h2><p>作品詳細とユーザープロフィールの「問題を報告」から、対象と詳細情報を確認できる共通ダイアログを開きます。明示的な送信操作で既存の ViewModel → Repository → PixivApiClient の経路を呼びます。</p><p>既存 API は <code>v1/illust/report</code> と <code>v1/user/report</code> への認証付き POST です。今回、エンドポイントや認証更新処理は変更していません。理由コードは参照元で確認できないため <code>type_of_problem</code> を追加せず、入力した内容を <code>message</code> として渡します。空白のみの入力は省略します。</p><p>送信中は送信・キャンセル操作を無効にし、成功時のみ閉じます。失敗時は入力を保持し、再試行と公式サイトを開く操作を提供します。公式サイトでの送信は、利用者が対象ページの「問題を報告」から行います。ブラウザー側のログインが必要な場合があります。</p><h2 id="検証の範囲" tabindex="-1">検証の範囲 <a class="header-anchor" href="#検証の範囲" aria-label="Permalink to &quot;検証の範囲&quot;">​</a></h2><p>実在する作品・ユーザーへの通報は送信していません。既存エンドポイントが現在の Pixiv サーバーで受理されることや、運営による受付・処理は未検証です。pixez-flutter の解析のみではこの仕様は確定できません。</p><p>手動確認項目:</p><ol><li>作品詳細とプロフィールのメニューから対象に対応した確認画面が開く。</li><li>キャンセルでは送信やミュートを行わない。</li><li>送信中に連打してもダイアログから追加の送信を開始しない。</li><li>通信エラー時に入力が残り、再試行できる。</li><li>失敗後のブラウザー操作で対象の作品／ユーザーページが開く。</li></ol><p>公式の通報案内: <a href="https://www.pixiv.help/hc/ja/articles/235645027" target="_blank" rel="noreferrer">迷惑行為・違反作品に対する対応</a></p>',14)])])}const u=i(l,[["render",o]]);export{_ as __pageData,u as default};
